<?php defined('ABSPATH')||exit;get_header();while(have_posts()):the_post();$id=get_the_ID();$types=wp_get_post_terms($id,'workshop_type',['fields'=>'names']);$brands=wp_get_post_terms($id,'workshop_brand',['fields'=>'names']);$difficulty=ss_workshop_meta($id,'_ss_difficulty');$time=ss_workshop_meta($id,'_ss_build_time');?>
<main><article class="workshop-single"><header class="workshop-article-head"><div class="wrap narrow"><div class="eyebrow"><?php echo esc_html($types?implode(' · ',$types):'Workshop');?></div><h1><?php the_title();?></h1><p class="ss-lead"><?php echo esc_html(get_the_excerpt());?></p><div class="article-facts"><?php if($brands):?><span><b>BRAND / TOPIC</b><?php echo esc_html(implode(' · ',$brands));?></span><?php endif;?><?php if($difficulty):?><span><b>LEVEL</b><?php echo esc_html($difficulty);?></span><?php endif;?><?php if($time):?><span><b>BENCH TIME</b><?php echo esc_html($time);?></span><?php endif;?><span><b>PUBLISHED</b><?php echo esc_html(get_the_date());?></span></div></div></header>
<?php $hero=get_the_post_thumbnail_url($id,'full');if(!$hero)$hero=get_post_meta($id,'_ss_remote_image',true);if($hero):?><div class="wrap workshop-featured"><img src="<?php echo esc_url($hero);?>" alt="<?php echo esc_attr(get_the_title());?>" loading="eager" decoding="async"></div><?php endif;?>
<section class="section"><div class="wrap narrow workshop-body"><?php the_content();?></div></section>
<section class="workshop-cta"><div class="wrap"><div><div class="eyebrow">Back to the bench</div><h2>KEEP BUILDING.</h2></div><a class="btn" href="<?php echo esc_url(ss_workshop_url());?>">MORE WORKSHOP ARTICLES</a></div></section></article></main><?php endwhile;get_footer();?>